function OverseaClubBossRecordNode:Refresh(data,isNext)
    self.record = checkTable(data)
    local count = table.count(self.record)
    KTool.SetActive(self.Empty.gameObject,count <= 0)
    KTool.SetActive(self.ScrollView.gameObject,count > 0)
    if count > 0 then
        self:RefreshListView(self.record)
    else
        if not isNull(self.TextDesc) then
            local status = isNext and 2 or 1
            CfUtils.SetUISwitchText(self.TextDesc,status)
        end
    end

    if self.BtnCheck then
        KTool.SetActive(self.BtnCheck.gameObject,not isNext)
    end
end

function OverseaClubBossRecordNode:RefreshListView(data)
    if self.ScrollView then
        if not self.ScrollView.IsListViewInit then
            self.ScrollView:InitListView(#data, Bind(self, self.OnRefreshCellIndex))
        else
            GameUtils.ReloadData(self.ScrollView, #data)
        end
    end
end

function OverseaClubBossRecordNode:OnRefreshCellIndex(listView,index)
    if index < 0 or index >= #self.record then
        return
    end

    local cell = listView:NewListViewItem(Cell)
    if not isNull(cell) then
        local tableCellEnv = CfUtils.GetLuaScr(cell, CellPath)
        if not isNull(tableCellEnv) then
            tableCellEnv:RefreshShow(self.record[index + 1])
        end
    end
    return cell
end

